// === Tab: mySketch.js ===
let fireworks = [];

// ----------------------------------------------------
// setup
// ----------------------------------------------------
function setup() {

  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 100);
  background(0, 0, 5);

  let labels = ["1", "2", "3", "4"];

  for (let i = 0; i < labels.length; i++) {

    let btn = createButton(labels[i]);

    btn.position(60 + i * 90, height - 80);

    btn.style('width', '60px');
    btn.style('height', '60px');
    btn.style('border-radius', '50%');
    btn.style('background', 'rgba(255,255,255,0.1)');
    btn.style('color', '#fff');

    btn.mousePressed(() => spawn(labels[i]));
  }
}

// ----------------------------------------------------
// 鍵盤 + 按鈕
// ----------------------------------------------------
function keyPressed() {
  spawn(key);
}

// ----------------------------------------------------
// 發射煙火
// ----------------------------------------------------
function spawn(k) {

  let hue;

  switch (k) {
    case "1": hue = 120; break; // 綠
    case "2": hue = 220; break; // 藍
    case "3": hue = 0;   break; // 紅
    case "4": hue = 280; break; // 紫
    default: return;
  }

  fireworks.push(new Firework(hue));
}

// ----------------------------------------------------
// draw
// ----------------------------------------------------
function draw() {

  background(0, 0, 5, 10);

  for (let i = fireworks.length - 1; i >= 0; i--) {

    let f = fireworks[i];

    f.update();
    f.display();

    if (f.dead()) {
      fireworks.splice(i, 1);
    }
  }
}

// ----------------------------------------------------
// FIREWORK（方案3 / 方案4 完全分離）
// ----------------------------------------------------
class Firework {

  constructor(hue) {

    this.hue = hue;

    // ✔ 每顆煙火隨機一種完整方案
    this.effectType = random(["type3", "type4"]);

    this.exploded = false;
    this.particles = [];

    this.rocket = new Particle(
      random(width * 0.2, width * 0.8),
      height,
      true,
      hue
    );
  }

  dead() {
    return this.exploded && this.particles.length === 0;
  }

  update() {

    // -----------------------------
    // 火箭
    // -----------------------------
    if (!this.exploded) {

      this.rocket.applyForce(0, 0.25);
      this.rocket.update();

      if (this.rocket.vy > -0.5) {
        this.exploded = true;
        this.explode();
      }
    }

    // -----------------------------
    // 粒子更新
    // -----------------------------
    for (let i = this.particles.length - 1; i >= 0; i--) {

      let p = this.particles[i];

      p.applyForce(0, 0.15);
      p.update();

      // ⭐⭐⭐ 重點：只有 type3 才允許二次爆炸
      if (
        this.effectType === "type3" &&
        p.canSecond &&
        !p.second &&
        p.life < 120 &&
        random() < 0.08
      ) {

        p.second = true;

        let h = (this.hue + random(-35, 35) + 360) % 360;

        for (let j = 0; j < 8; j++) {

          let child = new Particle(
            p.x,
            p.y,
            false,
            h
          );

          child.bigStyle = true;

          this.particles.push(child);
        }
      }

      if (p.life <= 0) {
        this.particles.splice(i, 1);
      }
    }
  }

  // ------------------------------------------------
  // 爆炸（完全分離）
  // ------------------------------------------------
  explode() {

    // =========================
    // 方案3（華麗 + 二次爆炸）
    // =========================
    if (this.effectType === "type3") {

      for (let i = 0; i < 130; i++) {

        var p = new Particle(
          this.rocket.x,
          this.rocket.y,
          false,
          this.hue
        );

        p.bigStyle = true;
        p.canSecond = true;

        this.particles.push(p);
      }
    }

    // =========================
    // 方案4（簡潔 + 無二次爆炸）
    // =========================
    else {

      for (let i = 0; i < 80; i++) {

        var p = new Particle(
          this.rocket.x,
          this.rocket.y,
          false,
          this.hue
        );

        // ⭐ 關鍵：完全封鎖二次爆炸
        p.bigStyle = false;
        p.canSecond = false;

        this.particles.push(p);
      }
    }
  }

  display() {

    if (!this.exploded) {
      this.rocket.draw();
    }

    for (let p of this.particles) {
      p.draw();
    }
  }
}

// ----------------------------------------------------
// PARTICLE
// ----------------------------------------------------
class Particle {

  constructor(x, y, rocket, hue) {

    this.x = x;
    this.y = y;

    this.rocket = rocket;
    this.hue = hue;

    this.life = 255;

    this.vx = 0;
    this.vy = 0;

    this.ax = 0;
    this.ay = 0;

    this.canSecond = false;
    this.second = false;
    this.bigStyle = false;

     // 火箭拖尾軌跡
    this.trail = [];

    if (rocket) {

      this.vx = random(-5, 5);
      this.vy = random(-18, -10);

    } else {

      let a = random(TWO_PI);
      let s = random(2, 10);

      this.vx = cos(a) * s;
      this.vy = sin(a) * s;
    }
  }

  applyForce(x, y) {
    this.ax += x;
    this.ay += y;
  }

  update() {

    if (!this.rocket) {
      this.vx *= 0.92;
      this.life -= 2;
    }

    this.vx += this.ax;
    this.vy += this.ay;

    this.x += this.vx;
    this.y += this.vy;

     // 火箭記錄軌跡
    if (this.rocket) {

      this.trail.push({
         x: this.x,
         y: this.y
      });

      if (this.trail.length > 25) {
        this.trail.shift();
      }
    }

    this.ax = 0;
    this.ay = 0;
  }

  draw() {

    var a = map(this.life, 0, 255, 0, 100);

  // ======================
  // 火箭軌跡
  // ======================
    if (this.rocket) {

      noFill();

      for (let i = 1; i < this.trail.length; i++) {

        let alpha = map(
          i,
          0,
          this.trail.length,
          0,
          80
        );

      // 金色尾焰
        stroke(
          45,
          90,
          100,
          alpha
        );

        strokeWeight(2);

        line(
          this.trail[i - 1].x,
          this.trail[i - 1].y,
          this.trail[i].x,
          this.trail[i].y
        );
      }

    // 火箭本體
      stroke(this.hue, 100, 100);
      strokeWeight(6);

      point(this.x, this.y);

      return;
    }

  // ======================
  // 煙火粒子
  // ======================
    stroke(this.hue, 100, 100, a);

	 if (this.second) {

      strokeWeight(1);

    } else {

      strokeWeight(
        this.bigStyle
          ? random(2, 4)
          : random(1, 2)
      );
    }

    point(this.x, this.y);
  }
}

// ----------------------------------------------------
function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
}

